// Loads the 36 species and the zones generated by scripts/extract-fish.mjs.
export async function loadData(url = '/assets/data/fish.json') {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Cannot load ${url}: ${response.status}`);
  const { zones, species } = await response.json();
  return { zones, species, speciesById: Object.fromEntries(species.map(s => [s.id, s])) };
}
